from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for character-prefix reuse in serialized rows."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and basic shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Serialize one scalar as scoring does, converting scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the common-prefix length using logarithmic C-level slice comparisons."""
        limit = min(len(left), len(right))
        low, high = 0, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse from sorted adjacent serialized strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        previous = ordered[0]
        total = 0
        for current in ordered[1:]:
            total += cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize every source row according to its row-specific column permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    def _global_order(self, cells, alternate: bool = False) -> List[int]:
        """Rank columns by repeated-value character pair mass with deterministic ties."""
        n, m = cells.shape
        ranked = []

        for column in range(m):
            counts = {}
            total_length = 0
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
                total_length += len(value)

            pair_mass = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            pair_count = sum(
                count * (count - 1)
                for count in counts.values()
            )

            if alternate:
                score = (
                    pair_mass * 2
                    + pair_count * max(1, total_length // max(1, n))
                )
            else:
                score = pair_mass

            ranked.append((score, pair_count, column))

        ranked.sort(key=lambda item: (-item[0], -item[1], item[2]))
        return [column for _, _, column in ranked]

    def _routing_orders(self, cells, global_order) -> List[List[int]]:
        """Build row-specific orders by bounded prototype-prefix character routing."""
        n, m = cells.shape
        if n == 0 or m == 0:
            return [[] for _ in range(n)]

        route_width = min(m, 12)
        prototype_limit = min(n, 512)
        first_column = global_order[0]
        second_column = global_order[1] if m > 1 else None

        signatures = []
        for row in range(n):
            first = cells[row, first_column]
            second = cells[row, second_column] if second_column is not None else ""
            signatures.append((first, second, row))
        signatures.sort(key=lambda item: (item[0], item[1], item[2]))

        if n <= prototype_limit:
            prototypes = [item[2] for item in signatures]
        else:
            prototypes = [
                signatures[(index * n) // prototype_limit][2]
                for index in range(prototype_limit)
            ]

        buckets = {}
        for prototype in prototypes:
            key = (
                cells[prototype, first_column],
                cells[prototype, second_column]
                if second_column is not None else "",
            )
            buckets.setdefault(key, []).append(prototype)

        rank = {column: index for index, column in enumerate(global_order)}
        result = []

        for row in range(n):
            key = (
                cells[row, first_column],
                cells[row, second_column] if second_column is not None else "",
            )
            bucket = buckets.get(key)

            if bucket:
                prototype = bucket[row % len(bucket)]
            else:
                prototype = prototypes[
                    min((row * prototype_limit) // max(1, n),
                        prototype_limit - 1)
                ]

            remaining = set(range(m))
            chosen = []

            for _ in range(route_width):
                if not remaining:
                    break

                proposals = []
                for column in global_order:
                    if column in remaining:
                        proposals.append(column)
                        if len(proposals) == 6:
                            break

                best_column = proposals[0]
                best_key = (-1, -1, 0)

                for column in proposals:
                    current = cells[row, column]
                    target = cells[prototype, column]
                    candidate_key = (
                        self._lcp(current, target),
                        len(current),
                        -rank[column],
                    )
                    if candidate_key > best_key:
                        best_key = candidate_key
                        best_column = column

                chosen.append(best_column)
                remaining.remove(best_column)

            chosen.extend(
                column for column in global_order
                if column in remaining
            )
            result.append(chosen)

        return result

    def _candidate(self, cells, orders):
        """Serialize one candidate, score its exact Trie reuse, and sort its rows canonically."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row),
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate two global orders and one bounded prototype-routed order losslessly."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        global_order = self._global_order(cells, False)
        alternate_order = self._global_order(cells, True)
        routed_orders = self._routing_orders(cells, global_order)

        candidates = (
            [[global_order[:] for _ in range(n)],
             [alternate_order[:] for _ in range(n)],
             routed_orders]
        )

        best = None
        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature))

            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, strings, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]
            output[destination, :] = [
                raw[source, column] for column in source_order
            ]
            column_orders.append([
                df.columns[column] for column in source_order
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders

